dius:7px;padding:7px 10px;font-size:10px;font-weight:700}.tab.active{background:var(--forest);color:#fff;border-color:var(--forest)}.detail-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.detail{padding:11px;background:#f6f8f5;border-radius:8px}.detail span{display:block;color:var(--muted);font-size:9px}.detail strong{display:block;color:var(--forest);font:800 17px Manrope;margin-top:6px}.detail small{font-size:9px;color:#87948d}.funnel{display:grid;gap:7px}.funnel-row{display:grid;grid-template-columns:130px 1fr 40px;gap:8px;align-items:center;font-size:10px;color:#586b62}.funnel-bar{height:11px;border-radius:8px;background:#eaf0e8;overflow:hidden}.funnel-bar span{display:block;height:100%;background:linear-gradient(90deg,#25845c,#b4d76d);border-radius:8px}.funnel strong{font-size:10px;color:var(--forest);text-align:right}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:10px}th{text-align:left;color:#718078;font-size:9px;padding:9px 7px;border-bottom:1px solid var(--line);white-space:nowrap}td{padding:9px 7px;border-bottom:1px solid #f0f2ef;color:#485b52;white-space:nowrap}.badge{display:inline-block;border-radius:20px;background:#edf4e9;color:var(--forest);padding:4px 7px;font-size:9px}.muted{color:var(--muted)}.pagination{display:flex;justify-content:space-between;align-items:center;padding-top:12px;font-size:10px;color:var(--muted)}.pagination button{border:1px solid var(--line);background:#fff;padding:6px 9px;border-radius:6px;color:var(--forest)}.note{border:1px solid #ebdfc8;background:#fff8ea;color:#725e3d;border-radius:8px;padding:10px 12px;font-size:10px;line-height:1.5;margin-bottom:14px}.eval{font-size:10px;color:#63746c;line-height:1.6}.eval strong{color:var(--forest)}.error{display:none;color:#a54335;background:#fff0ed;padding:9px;border-radius:7px;font-size:10px;margin-bottom:10px}
      @media(max-width:1200px){.cards{grid-template-columns:repeat(4,1fr)}}@media(max-width:850px){.shell{grid-template-columns:66px 1fr}.side{padding:20px 8px}.brand{padding:0 5px 25px}.brand span:last-child,.side-label,.nav-text,.side-bottom{display:none}.nav{justify-content:center;padding:12px}.header{padding:0 18px}.content{padding:22px 18px}.grid,.grid.equal{grid-template-columns:1fr}}@media(max-width:540px){.shell{grid-template-columns:1fr}.side{display:none}.header{height:62px}.content{padding:18px 12px}.title-row{display:block}.title-row .button{margin-top:13px}.cards{grid-template-columns:repeat(2,1fr)}.stat:last-child{grid-column:span 2}.filters{gap:7px}.filter select{min-width:100px}.detail-grid{grid-template-columns:repeat(2,1fr)}.funnel-row{grid-template-columns:95px 1fr 32px}.chart-box{height:200px}}
